static computeUniqueKey({
        url,
        method = 'GET',
        payload,
        keepUrlFragment = false,
        useExtendedUniqueKey = false,
        alwaysEnqueue = false,
    }: ComputeUniqueKeyOptions) {
        const normalizedMethod = method.toUpperCase();
        const normalizedUrl = normalizeUrl(url, keepUrlFragment) || url; // It returns null when url is invalid, causing weird errors.

        let uniqueKey: string;

        if (!useExtendedUniqueKey) {
            if (normalizedMethod !== 'GET' && payload) {
                serviceLocator
                    .getLogger()
                    .warningOnce(
                        `We've encountered a ${normalizedMethod} Request with a payload. ` +
                            'This is fine. Just letting you know that if your requests point to the same URL ' +
                            'and differ only in method and payload, you should see the "useExtendedUniqueKey" option of Request constructor.',
                    );
            }
            uniqueKey = normalizedUrl;
        } else {
            const payloadHash = payload ? CrawleeRequest.hashPayload(payload) : '';
            uniqueKey = `${normalizedMethod}|${payloadHash}|${normalizedUrl}`;
        }

        if (alwaysEnqueue) {
            uniqueKey = `${cryptoRandomObjectId(17)}|${uniqueKey}`;
        }

        return uniqueKey;
    }

async addRequest(
        requestLike: Source,
        options: RequestQueueOperationOptions = {},
    ): Promise<RequestQueueOperationInfo> {
        const transaction = activeStorageTransaction();

        parseArgument(requestLike, schemas.anyObject);
        const { forefront } = parseArgument(options, operationOptionsSchema);

        if ('requestsFromUrl' in requestLike) {
            const requests = await this.fetchRequestsFromUrl(requestLike as InternalSource);
            const processedRequests = await this.addFetchedRequests(requestLike as InternalSource, requests, options);

            return { ...processedRequests[0], forefront };
        }

        parseArgument(requestLike, newRequestLikeSchema);

        const request = requestLike instanceof Request ? requestLike : new Request(requestLike as RequestOptions);

        if (transaction?.policy.requestQueue === 'deferred') {
            return this.addRequestDeferred(transaction, request, forefront);
        }

        const cacheKey = getRequestId(request.uniqueKey);
        const cachedInfo = this.#requestCache.get(cacheKey);

        if (cachedInfo) {
            request.id = cachedInfo.id;
            this.recordRequestJournalEntry(transaction, [request], forefront, true);
            return {
                wasAlreadyPresent: true,
                // We may assume that if request is in local cache then also the information if the
                // request was already handled is there because just one client should be using one queue.
                wasAlreadyHandled: cachedInfo.isHandled,
                requestId: cachedInfo.id,
                uniqueKey: cachedInfo.uniqueKey,
                forefront,
            };
        }

        this.#statsTracker.add('writeCount');
        const { processedRequests } = await this.backend.addBatchOfRequests([request], { forefront });
        this.recordRequestJournalEntry(transaction, [request], forefront, true);
        const queueOperationInfo = {
            ...processedRequests[0],
            uniqueKey: request.uniqueKey,
            forefront,
        } satisfies RequestQueueOperationInfo;

        this.cacheRequest(cacheKey, queueOperationInfo);
        this.#requestSeenCache.add(cacheKey, request.id!);

        return queueOperationInfo;
    }

async fetchNextRequest<T extends Dictionary = Dictionary>(): Promise<Request<T> | null> {
        rejectOperationInTransaction(
            'RequestQueue.fetchNextRequest()',
            'it is part of the crawler request-processing bookkeeping, which a transaction must not affect.',
        );

        if (this.#queuePausedForMigration) {
            return null;
        }

        this.#statsTracker.add('headItemReadCount');
        const schema = await this.backend.fetchNextRequest();
        if (!schema) return null;

        return Request.fromSchema<T>(schema);
    }

async markRequestAsHandled(request: Request): Promise<RequestQueueOperationInfo | null> {
        rejectOperationInTransaction(
            'RequestQueue.markRequestAsHandled()',
            'it is part of the crawler request-processing bookkeeping, which a transaction must not affect.',
        );

        parseArgument(request, handledRequestSchema);

        const forefront = this.#requestCache.get(getRequestId(request.uniqueKey))?.forefront ?? false;

        const handledAt = request.handledAt ?? new Date().toISOString();
        this.#statsTracker.add('writeCount');
        const processedRequest = await this.backend.markRequestAsHandled({
            ...(request as Request & { id: string }),
            handledAt,
        });

        // The request was not in progress (e.g. already handled) — nothing to do.
        if (!processedRequest) {
            return null;
        }

        request.handledAt = handledAt;

        const queueOperationInfo = {
            ...processedRequest,
            uniqueKey: request.uniqueKey,
            forefront,
        } satisfies RequestQueueOperationInfo;

        this.cacheRequest(getRequestId(request.uniqueKey), queueOperationInfo);

        return queueOperationInfo;
    }

async reclaimRequest(
        request: Request,
        options: RequestQueueOperationOptions = {},
    ): Promise<RequestQueueOperationInfo | null> {
        rejectOperationInTransaction(
            'RequestQueue.reclaimRequest()',
            'it is part of the crawler request-processing bookkeeping, which a transaction must not affect.',
        );

        parseArgument(request, reclaimedRequestSchema);
        const { forefront } = parseArgument(options, operationOptionsSchema);

        this.#statsTracker.add('writeCount');
        const processedRequest = await this.backend.reclaimRequest(request as Request & { id: string }, {
            forefront,
        });

        // The request was not in progress — nothing to reclaim.
        if (!processedRequest) {
            return null;
        }

        const queueOperationInfo = {
            ...processedRequest,
            uniqueKey: request.uniqueKey,
            forefront,
        } satisfies RequestQueueOperationInfo;
        this.cacheRequest(getRequestId(request.uniqueKey), queueOperationInfo);

        return queueOperationInfo;
    }

pub async fn add_batch_of_requests(
        &self,
        requests: Vec<Value>,
        forefront: bool,
    ) -> Result<AddRequestsResponse> {
        let mut inner = self.inner.lock().await;
        let mut processed = Vec::new();
        // Track unique_keys seen within *this* batch so a duplicate later in
        // the same call reports `was_already_present` (matching the JS client,
        // which keys its in-memory map by request id).
        let mut seen_in_batch: HashMap<String, ()> = HashMap::new();

        for request in requests {
            let unique_key = Self::extract_unique_key(&request)?;
            let request_id = unique_key_to_request_id(&unique_key);

            // Is this request handled already?
            let already_handled = inner
                .requests
                .get(&unique_key)
                .map(|e| e.order_no.is_none())
                .unwrap_or(false);

            if already_handled {
                processed.push(ProcessedRequest {
                    request_id,
                    unique_key,
                    was_already_present: true,
                    was_already_handled: true,
                });
                continue;
            }

            let already_present =
                inner.requests.contains_key(&unique_key) || seen_in_batch.contains_key(&unique_key);

            // Already pending and not requesting a forefront move: report it.
            if already_present && !forefront {
                processed.push(ProcessedRequest {
                    request_id,
                    unique_key,
                    was_already_present: true,
                    was_already_handled: false,
                });
                continue;
            }

            // Does the *incoming* request carry a non-null `handledAt`? If so it
            // is being added as already-handled (matches JS `_calculateOrderNo`,
            // which returns `null` whenever `request.handledAt` is set, causing
            // the JS `batchAddRequests` to bump `handledRequestCount` rather
            // than `pendingRequestCount`). A forefront move of an existing
            // pending request that *also* carries `handledAt` would be
            // contradictory — treat the `handledAt` intent as authoritative and
            // skip the forefront promotion, matching JS (which never promotes
            // a handled request into the forefront list).
            let add_as_handled = request
                .get("handledAt")
                .or_else(|| request.get("handled_at"))
                .map(|v| !v.is_null())
                .unwrap_or(false);

            // Compute the orderNo exactly like JS `_calculateOrderNo`: a plain
            // signed unix-millis timestamp (negative = forefront), or `null`
            // when the request is being added as already-handled.
            // Same-millisecond collisions are intentional and harmless —
            // ordering is resolved by `forefront_request_ids` + `insertion_seq`.
            let order_no = if add_as_handled {
                None
            } else {
                Some(self.calculate_order_no(forefront))
            };
            let insertion_seq = inner.insertion_counter;
            inner.insertion_counter += 1;

            // Build the persisted request: inject id + orderNo, preserving the
            // opaque user payload. `orderNo: null` marks the request as handled
            // on disk (matches the `mark_request_as_handled` write shape and
            // the `rebuild_index` reader, which treats null/missing orderNo as
            // handled).
            let mut to_write = request.clone();
            if let Value::Object(ref mut map) = to_write {
                map.insert("id".to_string(), Value::String(request_id.clone()));
                let order_no_value = match order_no {
                    Some(n) => Value::Number(n.into()),
                    None => Value::Null,
                };
                map.insert("orderNo".to_string(), order_no_value);
            }

            let file_path = self.get_request_path(&unique_key);
            let json = json_dumps(&to_write)?;
            atomic_write(&file_path, json.as_bytes()).await?;

            inner.requests.insert(
                unique_key.clone(),
                RequestEntry {
                    order_no,
                    insertion_seq,
                },
            );

            // Mirror JS: track forefront ids in an ordered list (LIFO on fetch).
            // A handled add never participates in fetch ordering, so it must
            // not enter the forefront list even if `forefront=true` was passed.
            if forefront && !add_as_handled {
                inner
                    .metadata
                    .forefront_request_ids
                    .push(unique_key.clone());
            }

            if !already_present {
                // Brand new request — bump counts. A forefront move of an
                // already-present request leaves counts unchanged.
                inner.metadata.total_request_count += 1;
                if add_as_handled {
                    inner.metadata.handled_request_count += 1;
                } else {
                    inner.metadata.pending_request_count += 1;
                }
            }

            seen_in_batch.insert(unique_key.clone(), ());

            processed.push(ProcessedRequest {
                request_id,
                unique_key,
                was_already_present: already_present,
                // Mirror JS: even when adding a fresh request that already
                // carries `handledAt`, the response reports
                // `was_already_handled: false`. (The JS comment: "that's how
                // API behaves.")
                was_already_handled: false,
            });
        }

        let now = self.clock.now();
        inner.metadata.base.accessed_at = now;
        inner.metadata.base.modified_at = now;
        let meta_json = json_dumps_value(&inner.metadata)?;
        atomic_write(&self.path.join(METADATA_FILENAME), meta_json.as_bytes()).await?;

        Ok(AddRequestsResponse {
            processed_requests: processed,
            unprocessed_requests: Vec::new(),
        })
    }

fn ordered_candidate_keys(&self, inner: &InnerState) -> Vec<String> {
        let now = self.clock.now().timestamp_millis();
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        let mut out: Vec<String> = Vec::new();

        // Forefront ids, most-recently-added first (LIFO), as JS does.
        for key in inner.metadata.forefront_request_ids.iter().rev() {
            if !seen.insert(key.clone()) {
                continue;
            }
            if let Some(entry) = inner.requests.get(key) {
                if matches!(entry.order_no, Some(n) if !Self::is_locked_order(n, now)) {
                    out.push(key.clone());
                }
            }
        }

        // Regular requests: ascending orderNo, stable insertion_seq tie-break.
        let mut regulars: Vec<(&String, i64, u64)> = inner
            .requests
            .iter()
            .filter_map(|(key, entry)| match entry.order_no {
                Some(n) if !Self::is_locked_order(n, now) && !seen.contains(key) => {
                    Some((key, n, entry.insertion_seq))
                }
                _ => None,
            })
            .collect();
        regulars.sort_by(|a, b| a.1.cmp(&b.1).then(a.2.cmp(&b.2)));
        for (key, _, _) in regulars {
            if seen.insert(key.clone()) {
                out.push(key.clone());
            }
        }

        out
    }

pub async fn fetch_next_request(&self) -> Result<Option<Value>> {
        let mut inner = self.inner.lock().await;

        let now = self.clock.now().timestamp_millis();
        let lock_millis = inner.lock_millis;

        let candidates = self.ordered_candidate_keys(&inner);

        for unique_key in candidates {
            let file_path = self.get_request_path(&unique_key);

            // Re-read the file: it is the source of truth for the lock. Another
            // consumer may have locked or handled it since we last indexed.
            let mut request: Value = match fs::read_to_string(&file_path).await {
                Ok(content) => match serde_json::from_str(&content) {
                    Ok(v) => v,
                    Err(_) => continue,
                },
                Err(_) => {
                    // File vanished — drop from index and move on.
                    inner.requests.remove(&unique_key);
                    continue;
                }
            };

            let disk_order = Self::read_order_no(&request);

            // Handled or locked on disk (by us-stale or a foreign consumer)?
            match disk_order {
                None => {
                    // Handled elsewhere — sync the index.
                    if let Some(entry) = inner.requests.get_mut(&unique_key) {
                        entry.order_no = None;
                    }
                    continue;
                }
                Some(n) if Self::is_locked_order(n, now) => {
                    // Locked elsewhere — sync the index and skip.
                    if let Some(entry) = inner.requests.get_mut(&unique_key) {
                        entry.order_no = Some(n);
                    }
                    continue;
                }
                Some(n) => {
                    // Fetchable. Lock it: push |orderNo| into the future,
                    // preserving sign (forefront stays forefront). This is the
                    // v3 model — the lock lives in orderNo itself.
                    let sign = if n > 0 { 1 } else { -1 };
                    let locked = (now + lock_millis) * sign;

                    if let Value::Object(ref mut map) = request {
                        map.insert("orderNo".to_string(), Value::Number(locked.into()));
                    }
                    let json = json_dumps(&request)?;
                    atomic_write(&file_path, json.as_bytes()).await?;

                    if let Some(entry) = inner.requests.get_mut(&unique_key) {
                        entry.order_no = Some(locked);
                    }

                    inner.metadata.base.accessed_at = self.clock.now();
                    let meta_json = json_dumps_value(&inner.metadata)?;
                    atomic_write(&self.path.join(METADATA_FILENAME), meta_json.as_bytes()).await?;

                    let request_id = unique_key_to_request_id(&unique_key);
                    inner.held_locks.insert(
                        request_id,
                        HeldRequestLock {
                            unique_key: unique_key.clone(),
                            order_no: locked,
                        },
                    );

                    // Strip the queue-owned lock field before handing the
                    // request to the caller; we persisted the locked orderNo to
                    // disk above. The caller hands the request back to
                    // mark_request_as_handled/reclaim_request, which re-derive
                    // these fields from uniqueKey, so the round-trip is safe.
                    Self::strip_queue_internals(&mut request);
                    return Ok(Some(request));
                }
            }
        }

        Ok(None)
    }

pub async fn mark_request_as_handled(
        &self,
        mut request: Value,
    ) -> Result<Option<ProcessedRequest>> {
        let unique_key = Self::extract_unique_key(&request)?;
        let request_id = unique_key_to_request_id(&unique_key);

        let mut inner = self.inner.lock().await;

        let file_path = self.get_request_path(&unique_key);
        if !file_path.exists() && !inner.requests.contains_key(&unique_key) {
            // Unknown request — nothing to do.
            inner.held_locks.remove(&request_id);
            return Ok(None);
        }

        // Already handled? Idempotent success.
        let was_handled = inner
            .requests
            .get(&unique_key)
            .map(|e| e.order_no.is_none())
            .unwrap_or(false);
        if was_handled {
            inner.held_locks.remove(&request_id);
            return Ok(Some(ProcessedRequest {
                request_id,
                unique_key,
                was_already_present: true,
                was_already_handled: true,
            }));
        }

        // Set handledAt + clear orderNo (null => handled).
        let now = self.clock.now();
        let handled_at_str = now.format("%Y-%m-%dT%H:%M:%S%.6f+00:00").to_string();
        if let Value::Object(ref mut map) = request {
            map.insert("handledAt".to_string(), Value::String(handled_at_str));
            map.insert("orderNo".to_string(), Value::Null);
            map.entry("id")
                .or_insert_with(|| Value::String(request_id.clone()));
        }

        let json = json_dumps(&request)?;
        atomic_write(&file_path, json.as_bytes()).await?;
        inner.held_locks.remove(&request_id);

        let insertion_seq = inner
            .requests
            .get(&unique_key)
            .map(|e| e.insertion_seq)
            .unwrap_or(0);
        inner.requests.insert(
            unique_key.clone(),
            RequestEntry {
                order_no: None,
                insertion_seq,
            },
        );
        // A handled request no longer participates in forefront ordering.
        inner
            .metadata
            .forefront_request_ids
            .retain(|k| k != &unique_key);

        inner.metadata.handled_request_count += 1;
        inner.metadata.pending_request_count =
            inner.metadata.pending_request_count.saturating_sub(1);
        inner.metadata.base.accessed_at = now;
        inner.metadata.base.modified_at = now;

        let meta_json = json_dumps_value(&inner.metadata)?;
        atomic_write(&self.path.join(METADATA_FILENAME), meta_json.as_bytes()).await?;

        Ok(Some(ProcessedRequest {
            request_id,
            unique_key,
            was_already_present: true,
            was_already_handled: true,
        }))
    }

pub async fn reclaim_request(
        &self,
        mut request: Value,
        forefront: bool,
    ) -> Result<Option<ProcessedRequest>> {
        let unique_key = Self::extract_unique_key(&request)?;
        let request_id = unique_key_to_request_id(&unique_key);

        let mut inner = self.inner.lock().await;

        let file_path = self.get_request_path(&unique_key);
        if !file_path.exists() && !inner.requests.contains_key(&unique_key) {
            inner.held_locks.remove(&request_id);
            return Ok(None);
        }

        // Already handled — can't reclaim.
        let was_handled = inner
            .requests
            .get(&unique_key)
            .map(|e| e.order_no.is_none())
            .unwrap_or(false);
        if was_handled {
            inner.held_locks.remove(&request_id);
            return Ok(None);
        }

        // Reset orderNo to "now" (unlocked, fetchable immediately), preserving
        // the forefront/regular sign — matching JS `deleteRequestLock`
        // (`forefront ? -start : start`).
        let order_no = self.calculate_order_no(forefront);

        if let Value::Object(ref mut map) = request {
            map.insert("orderNo".to_string(), Value::Number(order_no.into()));
            map.entry("id")
                .or_insert_with(|| Value::String(request_id.clone()));
        }

        let json = json_dumps(&request)?;
        atomic_write(&file_path, json.as_bytes()).await?;
        inner.held_locks.remove(&request_id);

        // Preserve the original insertion order for a reclaim; only mint a new
        // sequence if (somehow) the request wasn't already indexed.
        let insertion_seq = match inner.requests.get(&unique_key) {
            Some(e) => e.insertion_seq,
            None => {
                let s = inner.insertion_counter;
                inner.insertion_counter += 1;
                s
            }
        };
        inner.requests.insert(
            unique_key.clone(),
            RequestEntry {
                order_no: Some(order_no),
                insertion_seq,
            },
        );
        if forefront && !inner.metadata.forefront_request_ids.contains(&unique_key) {
            inner
                .metadata
                .forefront_request_ids
                .push(unique_key.clone());
        }

        let now_dt = self.clock.now();
        inner.metadata.base.accessed_at = now_dt;
        inner.metadata.base.modified_at = now_dt;
        let meta_json = json_dumps_value(&inner.metadata)?;
        atomic_write(&self.path.join(METADATA_FILENAME), meta_json.as_bytes()).await?;

        Ok(Some(ProcessedRequest {
            request_id,
            unique_key,
            was_already_present: true,
            was_already_handled: false,
        }))
    }

pub async fn set_expected_request_processing_time(&self, duration: chrono::Duration) {
        let millis = duration.num_milliseconds();
        let mut inner = self.inner.lock().await;
        if millis > inner.lock_millis {
            inner.lock_millis = millis;
        }
    }

pub async fn prolong_request_lock(
        &self,
        request_id: &str,
        duration: chrono::Duration,
    ) -> Result<bool> {
        let extension_millis = duration.num_milliseconds();
        if extension_millis <= 0 {
            return Err(StorageError::InvalidArgs(
                "lock extension must be greater than zero".to_string(),
            ));
        }

        let mut inner = self.inner.lock().await;
        let Some(held) = inner.held_locks.get(request_id).cloned() else {
            return Ok(false);
        };
        let file_path = self.get_request_path(&held.unique_key);
        let content = match fs::read_to_string(&file_path).await {
            Ok(content) => content,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                inner.held_locks.remove(request_id);
                inner.requests.remove(&held.unique_key);
                return Ok(false);
            }
            Err(error) => return Err(error.into()),
        };
        let mut request: Value = serde_json::from_str(&content)?;
        let same_request = Self::extract_unique_key(&request)
            .map(|key| key == held.unique_key)
            .unwrap_or(false)
            && request.get("id").and_then(Value::as_str) == Some(request_id);
        let disk_order = Self::read_order_no(&request);
        let now = self.clock.now().timestamp_millis();

        if !same_request
            || disk_order != Some(held.order_no)
            || !Self::is_locked_order(held.order_no, now)
        {
            inner.held_locks.remove(request_id);
            if let Some(entry) = inner.requests.get_mut(&held.unique_key) {
                entry.order_no = disk_order;
            }
            return Ok(false);
        }

        let magnitude = held
            .order_no
            .checked_abs()
            .and_then(|expiry| expiry.checked_add(extension_millis))
            .ok_or_else(|| {
                StorageError::InvalidArgs("lock extension exceeds the supported range".to_string())
            })?;
        let sign = if held.order_no > 0 { 1 } else { -1 };
        let extended = magnitude.checked_mul(sign).ok_or_else(|| {
            StorageError::InvalidArgs("lock extension exceeds the supported range".to_string())
        })?;

        if let Value::Object(ref mut map) = request {
            map.insert("orderNo".to_string(), Value::Number(extended.into()));
        }
        atomic_write(&file_path, json_dumps(&request)?.as_bytes()).await?;

        if let Some(entry) = inner.requests.get_mut(&held.unique_key) {
            entry.order_no = Some(extended);
        }
        inner.held_locks.insert(
            request_id.to_string(),
            HeldRequestLock {
                unique_key: held.unique_key,
                order_no: extended,
            },
        );
        inner.metadata.base.accessed_at = self.clock.now();
        let metadata = json_dumps_value(&inner.metadata)?;
        atomic_write(&self.path.join(METADATA_FILENAME), metadata.as_bytes()).await?;

        Ok(true)
    }

pub async fn persist_state(&self) {
        // Intentionally empty: state lives in the request files + metadata.
    }

private canRequestBeRetried(request: CrawlingRequest, error: Error) {
        // Request should never be retried, or the error encountered makes it not able to be retried.
        if (request.noRetry || error instanceof NonRetryableError) {
            return false;
        }

        // User requested retry (we ignore retry count here as its explicitly told by the user to retry)
        if (error instanceof RetryRequestError) {
            return true;
        }

        // Ensure there are more retries available for the request
        const maxRequestRetries = request.maxRetries ?? this.#maxRequestRetries;
        return request.retryCount < maxRequestRetries;
    }

private async requestFunctionErrorHandler(
        error: Error,
        crawlingContext: CrawlingContext,
        request: CrawlingRequest,
        source: IRequestManager,
    ): Promise<void> {
        if (error instanceof RequestThrottledError) {
            // The domain told us to come back later, so the request was never really attempted. Put it back where
            // it was, without recording a failure - it costs neither a retry nor session reputation.
            this.log.debug(`Deferring request because its domain is rate-limiting us. ${error.message}`, {
                id: request.id,
                url: request.url,
            });
            await source.reclaimRequest(request, { forefront: true });
            return;
        }

        request.pushErrorMessage(error);

        if (error instanceof CriticalError) {
            throw error;
        }

        const shouldRetryRequest = this.canRequestBeRetried(request, error);

        if (shouldRetryRequest) {
            await this.statistics.errorTrackerRetry.addAsync(error, crawlingContext);
            await this.#errorHandler?.(
                crawlingContext as CrawlingContext & Partial<ExtendedContext>, // valid cast - ExtendedContext transitively extends CrawlingContext
                error,
            );

            if (error instanceof SessionError) {
                crawlingContext.session?.retire();
            }

            if (!request.noRetry) {
                request.retryCount++;

                const { url, retryCount, id } = request;

                // We don't want to see the stack trace in the logs by default, when we are going to retry the request.
                // Thus, we print the full stack trace only when CRAWLEE_VERBOSE_LOG environment variable is set to true.
                const message = this.getMessageFromError(error);
                this.log.warning(`Reclaiming failed request back to the list or queue. ${message}`, {
                    id,
                    url,
                    retryCount,
                });

                await source.reclaimRequest(request);
                return;
            }
        }

        if (error instanceof SessionError) {
            crawlingContext.session?.retire();
        }

        // If the request is non-retryable, the error and snapshot aren't saved in the errorTrackerRetry object.
        // Therefore, we pass the crawlingContext to the errorTracker.add method, enabling snapshot capture.
        // This is to make sure the error snapshot is not duplicated in the errorTrackerRetry and errorTracker objects.
        const { noRetry, maxRetries } = request;
        if (noRetry || !maxRetries) {
            await this.statistics.errorTracker.addAsync(error, crawlingContext);
        } else {
            this.statistics.errorTracker.add(error);
        }

        // If we get here, the request is either not retryable
        // or failed more than retryCount times and will not be retried anymore.
        // Mark the request as failed and do not retry.
        await source.markRequestAsHandled(request);
        this.statistics.recordRequestFailure(request.id || request.uniqueKey, request.retryCount);

        await this.handleFailedRequestHandler(crawlingContext, error); // This function prints an error message.
    }

stop(reason = 'The crawler has been gracefully stopped.'): void {
        const run = this.#liveRun;

        if (run === undefined) {
            this.log.warning('Cannot stop a crawler that is not running.');
            return;
        }

        run.stop(reason);
    }

async teardown(): Promise<void> {
        const eventManager = serviceLocator.getEventManager();
        const ownsEventManager = this.#run?.ownsEventManager === true;

        // First, so that the pool writes its final state once - its teardown stops it listening before the
        // persistence event below goes out.
        await this.#sessionPoolDep.ifOwned(async (pool) => pool.teardown());

        // When this crawler initialized the event manager, its close() call emits
        // the final persistence event after the crawler-specific state has been
        // saved. External event managers still need an explicit event here.
        if (!ownsEventManager) {
            eventManager.emit(EventType.PERSIST_STATE, { isMigrating: false });
        }

        if (ownsEventManager) {
            await eventManager.close();
        }

        await this.#run?.end();
    }

hasCapacityForTask(_consumer?: ConcurrencyConsumer): boolean {
        this.warnIfNotRunning();

        if (this.#currentConcurrency >= this.#desiredConcurrency) {
            this.log.perf('Task will not run. Desired concurrency achieved.');
            return false;
        }

        const currentStatus = this.systemStatus.getCurrentStatus();
        const { isSystemIdle } = currentStatus;
        if (!isSystemIdle && this.#currentConcurrency >= this.#minConcurrency) {
            this.log.perf(
                'Task will not be run. System is overloaded.',
                currentStatus as unknown as Record<string, unknown>,
            );
            return false;
        }

        return true;
    }

tryRegisterTaskStart(consumer?: ConcurrencyConsumer): boolean {
        if (!this.hasCapacityForTask(consumer)) {
            return false;
        }

        if (this.isOverMaxRequestLimit) {
            this.log.perf('Task will not run. Maximum tasks per minute reached.');
            return false;
        }

        this.#currentConcurrency++;
        this.#tasksPerMinute[0]++;
        return true;
    }

async checkReadiness(): Promise<RequestSourceStatus> {
        await this.#ensureSubManagers();

        const now = Date.now();
        const dispatchable: Promise<T>[] = [];
        let readyAt: number | undefined;
        let stallCandidates: DomainState[] | undefined;

        for (const state of this.#domainStates.values()) {
            // A `Crawl-delay` can give a domain a clock before its first request gives it a queue - nothing
            // to fetch from and nothing to wait for until then.
            if (!this.#subManagers.has(state.domain)) {
                continue;
            }

            if (
                // Together: still turning us away, and has been without a break for longer than the window - a
                // domain that has merely been idle starts this clock at its first 429, not with idle time on it.
                state.rateLimitedSince !== 0 &&
                now - state.lastRateLimitedAt <= this.#maxDomainStallMs &&
                now - state.rateLimitedSince > this.#maxDomainStallMs
            ) {
                // Deliberately not dispatchable: a domain that has refused every request for the whole window
                // is not progress just because its backoff momentarily lapsed - that is what it does between 429s.
                (stallCandidates ??= []).push(state);
                continue;
            }

            const until = throttledUntil(state);

            if (now >= until) {
                dispatchable.push(this.#subManagers.get(state.domain)!);
            } else if (readyAt === undefined || until < readyAt) {
                readyAt = until;
            }
        }

        const inner = await this.#getInner();

        const probed = (
            await Promise.all([
                inner.checkReadiness(),
                ...dispatchable.map(async (subManager) => (await subManager).checkReadiness()),
            ])
        ).reduce(joinRequestSourceStatuses);

        // Anything dispatchable outranks a stalled or throttled domain, so we stop here without touching them.
        if (probed.status === 'ready') {
            return probed;
        }

        if (stallCandidates !== undefined) {
            const stalled = (
                await Promise.all(
                    stallCandidates.map(async (state) =>
                        (await (await this.#subManagers.get(state.domain)!).checkReadiness()).status === 'ready'
                            ? state
                            : null,
                    ),
                )
            ).filter((state) => state !== null);

            if (stalled.length > 0) {
                const summary = stalled
                    .map((state) => `"${state.domain}" (${((now - state.rateLimitedSince) / 1000).toFixed(0)}s)`)
                    .join(', ');

                return {
                    status: 'stalled',
                    reason:
                        `${summary} rate-limited every request for longer than maxDomainStallSecs ` +
                        `(${(this.#maxDomainStallMs / 1000).toFixed(0)}s). Waiting longer will not help - lower the ` +
                        `crawler's concurrency, or drop these domains. Their requests are still queued, so ` +
                        `re-running with \`purgeOnStart\` disabled will resume them if the rate limit lifts.`,
                };
            }
        }

        if (readyAt !== undefined) {
            return joinRequestSourceStatuses(probed, { status: 'waiting', readyAt });
        }

        // Batches still landing in the background are work nobody can see in a queue yet.
        if (this.#inProgressBatchCount > 0 && probed.status === 'finished') {
            return { status: 'waiting' };
        }

        return probed;
    }

#recordRateLimit(url: string, waitMs?: number): boolean {
        const state = this.#getDomainState(url);
        if (!state) {
            return false;
        }

        const now = Date.now();

        // Recorded before the burst suppression below, because a suppressed 429 is still the domain turning us
        // away - which is exactly what stall detection needs to know about.
        state.lastRateLimitedAt = now;
        if (state.rateLimitedSince === 0) {
            state.rateLimitedSince = now;
        }

        // Requests already in flight when the limit was hit all come back 429. They describe one rate-limit
        // event, so only the first advances the backoff - otherwise concurrency alone drives the exponent.
        // Only the backoff clock may suppress here: `crawlDelayUntil` is in the future after every dispatch,
        // so consulting it would discard every 429 the domain ever sends, `Retry-After` included.
        if (now < state.backoffUntil) {
            return true;
        }

        // A domain that has served us for a full extra backoff window is no longer rate-limiting; start over
        // rather than carrying the old exponent into an unrelated burst.
        if (now >= state.backoffDecaysAt) {
            state.consecutive429Count = 0;
        }

        state.consecutive429Count += 1;

        const waitGiven = waitMs !== undefined;
        let delayMs = waitGiven ? waitMs : this.#baseDelayMs * Math.pow(2, state.consecutive429Count - 1);

        if (delayMs > this.#maxDelayMs) {
            const source = waitGiven ? 'requested wait' : 'exponential backoff';
            this.#log.warning(
                `Capping ${source} delay of ${(delayMs / 1000).toFixed(1)}s for domain "${state.domain}" ` +
                    `to maxDelaySecs (${(this.#maxDelayMs / 1000).toFixed(1)}s); the domain may continue to rate-limit. ` +
                    `Consider increasing maxDelaySecs if this recurs.`,
            );
            delayMs = this.#maxDelayMs;
        }

        state.backoffUntil = now + delayMs;
        state.backoffDecaysAt = state.backoffUntil + delayMs;

        this.#log.info(
            `Rate limit (429) detected for domain "${state.domain}" ` +
                `(consecutive: ${state.consecutive429Count}, delay: ${(delayMs / 1000).toFixed(1)}s)`,
        );

        return true;
    }
